-- Isolated-test baseline: approved pre-Task196 constraints. NEVER run in production.
ALTER TABLE public.contracts_management DROP CONSTRAINT ck_contracts_management_revenue_basis;
ALTER TABLE public.contracts_management DROP CONSTRAINT ck_contracts_management_pricing_completeness;
ALTER TABLE public.contracts_management DROP CONSTRAINT ck_contracts_management_day_km_nonnegative;
ALTER TABLE public.contracts_management ADD CONSTRAINT ck_contracts_management_revenue_basis CHECK (cont_revenue_basis IN ('PER_PASSENGER', 'PER_BUS', 'PER_PASSENGER_AND_PER_BUS'));
ALTER TABLE public.contracts_management ADD CONSTRAINT ck_contracts_management_pricing_completeness CHECK ((((cont_status)::text = 'DRAFT'::text) OR (((cont_revenue_basis)::text = 'PER_PASSENGER'::text) AND (cont_no_of_passengers > 0) AND (cont_per_passenger_rate_pm IS NOT NULL)) OR (((cont_revenue_basis)::text = 'PER_BUS'::text) AND (cont_no_of_buses > 0) AND ((cont_big_bus_count_gt_34 = 0) OR (cont_big_bus_rate_pm IS NOT NULL)) AND ((cont_medium_bus_count_17_34 = 0) OR (cont_medium_bus_rate_pm IS NOT NULL)) AND ((cont_small_bus_count_lt_17 = 0) OR (cont_small_bus_rate_pm IS NOT NULL))) OR (((cont_revenue_basis)::text = 'PER_PASSENGER_AND_PER_BUS'::text) AND (cont_no_of_passengers > 0) AND (cont_per_passenger_rate_pm IS NOT NULL) AND (cont_no_of_buses > 0) AND ((cont_big_bus_count_gt_34 = 0) OR (cont_big_bus_rate_pm IS NOT NULL)) AND ((cont_medium_bus_count_17_34 = 0) OR (cont_medium_bus_rate_pm IS NOT NULL)) AND ((cont_small_bus_count_lt_17 = 0) OR (cont_small_bus_rate_pm IS NOT NULL)))));
